---@type OverseaStoreConstants
local OverseaStoreConstants = import('Game.OverseaStore.OverseaStoreConstants')

---@class OverseaStoreUtils
local OverseaStoreUtils = Class('OverseaStoreUtils')

local UIModule = CS.Engine.UI.UIModule

---打开商城首页
---@param storeType OverseaStoreConstants.StoreType | nil
---@param excludeIds  table   互斥页面
---@param exParameter table | nil 额外参数
---@param isStack     boolean 是否是导航条的跳转
function OverseaStoreUtils.OpenStore(storeType, excludeIds, exParameter, isStack)
    isStack = (not checkBool(isStack)) ---初始为true入栈的操作

    -- 判断当前商城是否开启
    local dialogs = UIModule.CurrentScreen.dialogs
    for _, v in pairs(dialogs) do
        if v.Argument.id == Constants.UITypeIds.OverseaStore then
            Events.Broadcast(Constants.EventNames.OVERSEA_STORE_DIALOG_SWITCH, storeType, exParameter)
            return
        end
    end
    
    local parameters = {}
    parameters.exParameter = exParameter
    parameters.storeType = storeType
    return UIModule.OpenDialog({ id = Constants.UITypeIds.OverseaStore, parameters = parameters }, excludeIds, isStack)
end

---商品是否锁定
function OverseaStoreUtils.ProductIsLocked(product)
    if not isSet(product, "unlock") or type(product.unlock) == 'function'  then
        return false
    end
    
    local isLocked = false
    local lockedDescr = ''
    for i = 1, #product.unlock do
        isLocked = isLocked or not GameUtils.IsUnlockedSingle(product.unlock[i].targetType, product.unlock[i].targetNum, product.unlock[i].targetId)
        if isLocked then
            lockedDescr = GameUtils.GetUnlockDescription(tostring(product.unlock[i].targetType), tostring(product.unlock[i].targetNum))
            break
        end
    end
    return isLocked, lockedDescr
end

---商品是否免费
function OverseaStoreUtils.ProductIsFree(product)
    if product.prices and table.count(product.prices) > 0 then
        for i = 1, #product.prices do
            if product.prices[i].current ~= 0 then
                return false
            end
        end
        return true
    end
    
    return checkInt(product.isFree) == 1
end

---商品是否售罄
function OverseaStoreUtils.ProductIsSoldOut(product)
    if not isSet(product, "currentStock") then
        return false
    end
    if product.stock ~= -1 then
        return product.currentStock == 0
    else
        return false
    end
end

---获取商城道具背景
---@param quality Constants.QualityType 道具品质
function OverseaStoreUtils.GetGoodsBgByQuality(quality)
    return string.format(OverseaStoreConstants.ImgPath.CellGoodsBg, quality or 1)
end

return OverseaStoreUtils